    d.table('Медианы синтетического benchmark',['p','t1 с','t2 с','t3 с','Медиана с','T1/Tp'],[[x['p']]+[sec(t) for t in x['times']]+[sec(x['median']),num(x['speedup'],3)] for x in r['benchmark']],[1.5,3,3,3,3,3])
