    d.table('Контроль самостоятельного repartition coalesce',['Способ','Минимум','Максимум','Среднее'],[[name,num(x['min'],0),num(x['max'],0),num(x['mean'])] for name,x in b['profiles'].items()],[5,3.5,4,4])
